import{n as e}from"./QTnfLwEv.js";var t=e({default:()=>n}),n={"faq.answer.web-apps-hosting-a1":`<p>We auto-detect and support all major modern frameworks:</p><b>Frontend-supported Applications</b><ul><li>React</li><li>Vue.js</li><li>Angular</li><li>Vite</li><li>Parcel</li><li>Preact</li><li>Next.js</li><li>Nuxt.js</li><li>Svelte</li><li>Astro</li><li>SvelteKit</li><li>React Router</li><li>Hono</li></ul><b>Backend-supported Applications</b><ul><li>Next.js</li><li>Express.js</li><li>NestJS</li><li>Nuxt.js</li><li>Fastify</li><li>Astro</li></ul><p>No manual configuration or YAML files required, just connect to GitHub or upload a ZIP file, and we’ll handle the rest. More supported frameworks will be added soon.</p>`,"faq.answer.web-apps-hosting-a2":`<p>This is fully managed hosting — we take care of uptime, scaling, and security, so you never touch the server side. VPS is great if you need root access and full control.</p><p>Web Apps Hosting is for developers who want to deploy instantly and skip DevOps altogether.</p>`,"faq.answer.web-apps-hosting-a3":`<p>You get unlimited bandwidth and requests, plus free managed SSLs and a free domain with business email for 1 year on annual plans. Your app scales freely with flat, predictable monthly pricing.</p>`,"faq.answer.web-apps-hosting-a4":`<p>Absolutely. You can connect private repos securely — deployments stay private, and we never expose your code. GitHub connect, ZIP upload, or webhook redeploys all work seamlessly.</p>`,"faq.answer.web-apps-hosting-a5":`<p>Yes. You can easily migrate your project by connecting your GitHub repository or uploading your files — your website will be deployed on Hostinger automatically.</p>`,"faq.question.web-apps-hosting-q1":`What frameworks are supported?`,"faq.question.web-apps-hosting-q2":`How is this different from VPS hosting?`,"faq.question.web-apps-hosting-q3":`Is there any traffic limit or overage fee?`,"faq.question.web-apps-hosting-q4":`Can I deploy private GitHub repositories?`,"faq.question.web-apps-hosting-q5":`Is there free migration support?`};export{t as n,n as t};